#!/usr/bin/env node
// Generates typed TypeScript catalogues from the canonical TOML locales.
//
// `locales/ru.toml` and `locales/en.toml` are the single source of strings for
// both Rust (`rust-i18n`) and React. Nested TOML tables become flat dotted keys,
// so `[delete.mode] recycle_bin = "..."` becomes `delete.mode.recycle_bin`.
//
// Usage:
//   node scripts/gen-i18n.mjs           write src/i18n/generated/*.ts
//   node scripts/gen-i18n.mjs --check   fail when the generated files are stale

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { parse } from 'smol-toml';

const HEADER = [
  '// This file is generated by scripts/gen-i18n.mjs.',
  '// Edit locales/<language>.toml instead; CI fails on a stale catalogue.',
  '',
].join('\n');

const scriptDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(scriptDir, '../../../..');
const localesDir = join(repoRoot, 'locales');
const outputDir = resolve(scriptDir, '../src/i18n/generated');
const checkOnly = process.argv.includes('--check');

/** Flattens nested TOML tables into dotted keys; `_`-prefixed keys are metadata. */
function flatten(value, prefix, target) {
  for (const [key, entry] of Object.entries(value)) {
    if (key.startsWith('_')) {
      continue;
    }

    const dotted = prefix === '' ? key : `${prefix}.${key}`;

    if (entry !== null && typeof entry === 'object' && !Array.isArray(entry)) {
      flatten(entry, dotted, target);
      continue;
    }

    if (typeof entry !== 'string') {
      throw new Error(`locale value "${dotted}" must be a string`);
    }

    target.set(dotted, entry);
  }
}

/** Reads and flattens one locale file. */
function loadLocale(language) {
  const file = join(localesDir, `${language}.toml`);
  const parsed = parse(readFileSync(file, 'utf8'));
  const flat = new Map();
  flatten(parsed, '', flat);
  return new Map([...flat.entries()].sort(([left], [right]) => left.localeCompare(right)));
}

/** Renders the `export const <language> = { ... } as const;` module. */
function renderLocale(language, entries) {
  const lines = [...entries.entries()].map(
    ([key, value]) => `  ${JSON.stringify(key)}: ${JSON.stringify(value)},`,
  );

  return `${HEADER}export const ${language} = {\n${lines.join('\n')}\n} as const;\n`;
}

/** Renders the union of message keys. */
function renderKeys(keys) {
  const lines = keys.map((key) => `  ${JSON.stringify(key)},`);

  return `${HEADER}export const messageKeys = [\n${lines.join('\n')}\n] as const;\n\nexport type MessageKey = (typeof messageKeys)[number];\n`;
}

/** Compares the key sets of both languages and fails on drift. */
function assertSameKeys(reference, other) {
  const missingInOther = [...reference.keys()].filter((key) => !other.has(key));
  const missingInReference = [...other.keys()].filter((key) => !reference.has(key));

  if (missingInOther.length === 0 && missingInReference.length === 0) {
    return;
  }

  const problems = [
    ...missingInOther.map((key) => `  missing in the other catalogue: ${key}`),
    ...missingInReference.map((key) => `  extra in the other catalogue: ${key}`),
  ];

  throw new Error(`locale catalogues drifted:\n${problems.join('\n')}`);
}

const ru = loadLocale('ru');
const en = loadLocale('en');
assertSameKeys(ru, en);

const outputs = new Map([
  ['ru.ts', renderLocale('ru', ru)],
  ['en.ts', renderLocale('en', en)],
  ['keys.ts', renderKeys([...ru.keys()])],
]);

let stale = false;

for (const [name, content] of outputs) {
  const target = join(outputDir, name);
  const current = existsSync(target) ? readFileSync(target, 'utf8') : null;

  if (current === content) {
    continue;
  }

  if (checkOnly) {
    console.error(`stale i18n catalogue: ${target}`);
    stale = true;
    continue;
  }

  writeFileSync(target, content, 'utf8');
  console.log(`wrote ${target}`);
}

if (stale) {
  console.error('run "npm run gen:i18n" and commit the generated catalogues');
  process.exitCode = 1;
}
